// Base64 woff2 subsets so composed creatives can embed the platform fonts
// (Inter + Noto Sans Arabic) inline. An SVG used as an image cannot load the
// Google Fonts stylesheet, so the exact wording is rendered in the main app
// typeface only when the font travels inside the SVG. Sources:
//   @fontsource/inter@5 inter-latin-600/700-normal.woff2
//   @fontsource/noto-sans-arabic@5 noto-sans-arabic-arabic-700-normal.woff2
export const INTER_600_WOFF2 = "";
export const INTER_700_WOFF2 = "";
export const NOTO_ARABIC_700_WOFF2 = "";
